import 'package:flutter/material.dart';
import 'package:flutter_chat_bubble/chat_bubble.dart';
import 'package:flutter_chat_bubble/bubble_type.dart';
import 'package:flutter_chat_bubble/clippers/chat_bubble_clipper_6.dart';

class CharacterSpeechBubble extends StatelessWidget {
  const CharacterSpeechBubble({
    super.key,
    required this.text,
    this.maxWidth = 240,
  });

  final String text;
  final double maxWidth;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return ConstrainedBox(
      constraints: BoxConstraints(maxWidth: maxWidth),
      child: ChatBubble(
        clipper: ChatBubbleClipper6(
          type: BubbleType.sendBubble, // ← 右側にしっぽ
        ),
        alignment: Alignment.bottomRight,
        margin: const EdgeInsets.only(bottom: 6),
        backGroundColor: theme.colorScheme.primary.withOpacity(0.95),
        child: Text(
          text,
          style: theme.textTheme.bodyMedium?.copyWith(
            color: Colors.white,
            height: 1.35,
            fontWeight: FontWeight.w500,
          ),
        ),
      ),
    );
  }
}

// lib/characters/character_speech_controller.dart
import 'dart:math';

import 'package:flutter/foundation.dart';

import 'character.dart';
import 'character_speech_key.dart';
import 'character_speech_provider.dart';
import 'character_speech_store.dart';

class CharacterSpeechController {
  CharacterSpeechController._();
  static final instance = CharacterSpeechController._();

  final ValueNotifier<String?> currentSpeech = ValueNotifier<String?>(null);

  final _rng = Random();

  /// HUDタップなどから呼ぶ
  Future<void> show({
    required Character character,
    required CharacterSpeechKey key,
  }) async {
    final candidates = CharacterSpeechProvider.lines(
      key,
      character: character,
      // ここで DateTime.now() は Provider 側で補完しているので渡さなくてOK
    );

    if (candidates.isEmpty) {
      currentSpeech.value = null;
      return;
    }

    final recent = await CharacterSpeechStore.instance.getRecent(
      character: character,
      key: key,
    );

    // 直近と被らない候補を優先
    final fresh = candidates.where((s) => !recent.contains(s)).toList();
    final pool = fresh.isNotEmpty ? fresh : candidates;

    final next = pool[_rng.nextInt(pool.length)];
    currentSpeech.value = next;

    await CharacterSpeechStore.instance.pushRecent(
      character: character,
      key: key,
      line: next,
    );
  }

  void clear() {
    currentSpeech.value = null;
  }
}

// lib/characters/character_speech_engine.dart
import 'dart:math';

class CharacterSpeechEngine {
  CharacterSpeechEngine._();

  static final _rng = Random();

  /// candidates から「直近の recent を避けて」選ぶ
  /// - 全部 recent なら candidates からランダム
  static String pick({
    required List<String> candidates,
    required List<String> recent,
  }) {
    if (candidates.isEmpty) return '';

    final recentSet = recent.toSet();

    final pool = candidates.where((s) => !recentSet.contains(s)).toList();
    final list = pool.isNotEmpty ? pool : candidates;

    return list[_rng.nextInt(list.length)];
  }
}

