    switch (b) {
      case _TimeBucket.morning:
        return [
          'おはよう！今日もいっしょにいこう！',
          '朝の1問、気持ちいいぞ！',
          '準備OK？まずは軽く解いてみよう！',
        ];
      case _TimeBucket.day:
        return [
          'いいペース！その調子！',
          '今のうちにコツコツ積もう！',
          '1問ずつで十分強くなる！',
        ];
      case _TimeBucket.evening:
        return [
          '今日の分、回収しよう！',
          '疲れてても1問でOK！',
          '夜は復習が伸びる時間！',
        ];
      case _TimeBucket.night:
        return [
          '無理しすぎ注意だぞ！',
          '眠くなる前に1問だけでも！',
          '休むのも実力！',
        ];
    }
  }

  static List<String> _naccoHome(_TimeBucket b) {
    switch (b) {
      case _TimeBucket.morning:
        return [
          'おはよ〜！今日もゆるっと積み上げよ〜',
          '朝は深呼吸してから1問いこっ',
          'あったかい飲み物、用意した？',
        ];
      case _TimeBucket.day:
        return [
          'いい感じ〜！焦らずいこ〜',
          'わからなくても大丈夫、解説で伸びる〜',
          'コツコツが一番強いんだよ〜',
        ];
      case _TimeBucket.evening:
        return [
          '今日もおつかれ〜！復習で仕上げよ〜',
          '夜は記憶がまとまりやすいかも〜',
          'やさしく丁寧にいこ〜',
        ];
      case _TimeBucket.night:
        return [
          '眠いときは休んでOKだよ〜',
          '無理しないのが最強〜',
          '明日の自分にバトンタッチ〜',
        ];
    }
  }

  static List<String> _nayuHome(_TimeBucket b) {
    switch (b) {
      case _TimeBucket.morning:
        return [
          'おはようにゃ！まずは1問にゃ！',
          '朝の集中力は貴重にゃ〜',
          'ゆっくりでいいにゃ、始めよ！',
        ];
      case _TimeBucket.day:
        return [
          'いい流れにゃ！',
          'その1問が合格に近づくにゃ！',
          '今日の積み上げ、偉いにゃ！',
        ];
      case _TimeBucket.evening:
        return [
          '今日の復習が効くにゃ〜',
